def depths(self):
    """Create a mapping of tree clades to depths (by branch length).

    @returns: dict of {clade: depth}
    """
    depths = {}
    queue = [(self.root, 0)]  # (node, current_depth)
    while queue:
        node, current_depth = queue.pop(0)
        depths[node] = current_depth
        for child in node.children:
            queue.append((child, current_depth + child.branch_length))
    return depths
